### Objective
Build an enterprise-grade, resilient Live Crypto Exchange Ticker in Flutter using `web_socket_channel`. Demonstrate robust connection lifecycle handling, an automated heartbeat watchdog, exponential backoff reconnection with jitter, broadcast stream splitting to multiple UI widgets, and a live pricing card that flashes color on price changes.

```dart
import 'dart:async';
import 'dart:convert';
import 'dart:math';
import 'package:flutter/material.dart';
import 'package:web_socket_channel/web_socket_channel.dart';

void main() {
  runApp(const CryptoLiveStreamApp());
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. DOMAIN MODELS & CONNECTION STATUS
// ─────────────────────────────────────────────────────────────────────────────

enum SocketStatus { connecting, connected, disconnected, reconnecting }

class MarketTick {
  final String symbol;
  final double price;
  final double volume;
  final DateTime timestamp;

  const MarketTick({
    required this.symbol,
    required this.price,
    required this.volume,
    required this.timestamp,
  });

  factory MarketTick.fromJson(Map<String, dynamic> json) {
    return MarketTick(
      symbol: json['s'] as String? ?? 'BTCUSDT',
      price: double.tryParse(json['p']?.toString() ?? '0.0') ?? 0.0,
      volume: double.tryParse(json['q']?.toString() ?? '0.0') ?? 0.0,
      timestamp: DateTime.fromMillisecondsSinceEpoch(
        (json['T'] as num?)?.toInt() ?? DateTime.now().millisecondsSinceEpoch,
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. RESILIENT WEBSOCKET MANAGER WITH HEARTBEAT & BACKOFF
// ─────────────────────────────────────────────────────────────────────────────

class ResilientWebSocketService {
  final Uri serverUri;
  WebSocketChannel? _channel;
  StreamSubscription? _channelSubscription;

  // Broadcast controllers allow multiple UI components to listen independently
  final _marketDataController = StreamController<MarketTick>.broadcast();
  final _statusController = StreamController<SocketStatus>.broadcast();

  Stream<MarketTick> get marketStream => _marketDataController.stream;
  Stream<SocketStatus> get statusStream => _statusController.stream;

  bool _isDisposed = false;
  int _reconnectAttempts = 0;
  static const int _maxBackoffSeconds = 30;

  Timer? _heartbeatTimer;
  Timer? _pongWatchdogTimer;
  static const Duration _heartbeatInterval = Duration(seconds: 15);
  static const Duration _pongTimeout = Duration(seconds: 4);

  ResilientWebSocketService({required this.serverUri});

  void connect() {
    if (_isDisposed) return;

    _statusController.add(
      _reconnectAttempts > 0 ? SocketStatus.reconnecting : SocketStatus.connecting,
    );

    try {
      _channel = WebSocketChannel.connect(serverUri);

      _channelSubscription = _channel!.stream.listen(
        (rawMessage) => _handleIncomingMessage(rawMessage),
        onError: (error) {
          debugPrint('🚨 [WS ERROR] Socket encountered error: $error');
          _scheduleReconnect();
        },
        onDone: () {
          debugPrint('🔌 [WS DISCONNECTED] Connection terminated by remote host.');
          _scheduleReconnect();
        },
        cancelOnError: true,
      );

      _statusController.add(SocketStatus.connected);
      _reconnectAttempts = 0; // Reset backoff counter on successful link
      _startHeartbeat();
    } catch (e) {
      debugPrint('🚨 [WS CONNECT FAILURE] $e');
      _scheduleReconnect();
    }
  }

  void _handleIncomingMessage(dynamic rawMessage) {
    try {
      final decoded = jsonDecode(rawMessage.toString()) as Map<String, dynamic>;

      // Intercept heartbeat pong frames
      if (decoded['type'] == 'pong') {
        _pongWatchdogTimer?.cancel();
        return;
      }

      // Map incoming trading payload
      final tick = MarketTick.fromJson(decoded);
      _marketDataController.add(tick);
    } catch (e) {
      debugPrint('⚠️ [WS DESERIALIZATION ERROR] Failed to parse frame: $e');
    }
  }

  void _startHeartbeat() {
    _heartbeatTimer?.cancel();
    _heartbeatTimer = Timer.periodic(_heartbeatInterval, (_) {
      _sendPing();
    });
  }

  void _sendPing() {
    if (_channel == null) return;

    try {
      _channel!.sink.add(jsonEncode({'type': 'ping', 't': DateTime.now().millisecondsSinceEpoch}));

      // Start watchdog timer: if server does not respond with pong within 4s, abort socket
      _pongWatchdogTimer?.cancel();
      _pongWatchdogTimer = Timer(_pongTimeout, () {
        debugPrint('💀 [WS HALF-OPEN DETECTED] Heartbeat missed! Forcing socket closure...');
        _teardownActiveSocket();
        _scheduleReconnect();
      });
    } catch (e) {
      debugPrint('🚨 [WS PING FAILED] Sink write error: $e');
    }
  }

  void _scheduleReconnect() {
    _teardownActiveSocket();
    if (_isDisposed) return;

    _statusController.add(SocketStatus.disconnected);
    _reconnectAttempts++;

    // Exponential backoff with randomized jitter formula
    final baseBackoff = min(pow(2, _reconnectAttempts).toInt(), _maxBackoffSeconds);
    final jitter = Random().nextInt(1000); // 0-999ms jitter
    final delay = Duration(milliseconds: (baseBackoff * 1000) + jitter);

    debugPrint('⏳ [WS RECONNECT] Scheduling attempt #$_reconnectAttempts in ${delay.inMilliseconds}ms');

    Timer(delay, () {
      if (!_isDisposed) connect();
    });
  }

  void sendMessage(Map<String, dynamic> payload) {
    if (_channel != null) {
      _channel!.sink.add(jsonEncode(payload));
    }
  }

  void _teardownActiveSocket() {
    _heartbeatTimer?.cancel();
    _pongWatchdogTimer?.cancel();
    _channelSubscription?.cancel();
    _channelSubscription = null;
    try {
      _channel?.sink.close();
    } catch (_) {}
    _channel = null;
  }

  void dispose() {
    _isDisposed = true;
    _teardownActiveSocket();
    _marketDataController.close();
    _statusController.close();
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. PRESENTATION LAYER
// ─────────────────────────────────────────────────────────────────────────────

class CryptoLiveStreamApp extends StatelessWidget {
  const CryptoLiveStreamApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Real-Time WebSocket Architecture',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.amber,
        useMaterial3: true,
      ),
      home: const CryptoTickerScreen(),
    );
  }
}

class CryptoTickerScreen extends StatefulWidget {
  const CryptoTickerScreen({super.key});

  @override
  State<CryptoTickerScreen> createState() => _CryptoTickerScreenState();
}

class _CryptoTickerScreenState extends State<CryptoTickerScreen> {
  late final ResilientWebSocketService _wsService;
  double _lastPrice = 0.0;
  Color _flashColor = Colors.transparent;

  @override
  void initState() {
    super.initState();
    // Connect to public Binance raw trade WebSocket stream
    _wsService = ResilientWebSocketService(
      serverUri: Uri.parse('wss://stream.binance.com:9443/ws/btcusdt@trade'),
    )..connect();
  }

  @override
  void dispose() {
    _wsService.dispose();
    super.dispose();
  }

  void _handlePriceUpdate(MarketTick tick) {
    if (_lastPrice != 0.0 && tick.price != _lastPrice) {
      final isUp = tick.price > _lastPrice;
      setState(() {
        _flashColor = isUp ? Colors.green.withValues(alpha: 0.2) : Colors.red.withValues(alpha: 0.2);
      });

      Future.delayed(const Duration(milliseconds: 300), () {
        if (mounted) {
          setState(() {
            _flashColor = Colors.transparent;
          });
        }
      });
    }
    _lastPrice = tick.price;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Live Crypto Ticker (WSS)'),
        centerTitle: true,
        actions: [
          // Connection Status Indicator Pill
          StreamBuilder<SocketStatus>(
            stream: _wsService.statusStream,
            initialData: SocketStatus.connecting,
            builder: (context, snapshot) {
              final status = snapshot.data ?? SocketStatus.disconnected;
              final (color, label) = switch (status) {
                SocketStatus.connected => (Colors.green, 'LIVE'),
                SocketStatus.connecting => (Colors.orange, 'CONNECTING'),
                SocketStatus.reconnecting => (Colors.amber, 'RECONNECTING'),
                SocketStatus.disconnected => (Colors.red, 'OFFLINE'),
              };

              return Padding(
                padding: const EdgeInsets.only(right: 16.0),
                child: Center(
                  child: Container(
                    padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                    decoration: BoxDecoration(
                      color: color.withValues(alpha: 0.15),
                      borderRadius: BorderRadius.circular(12),
                      border: Border.all(color: color),
                    ),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        CircleAvatar(radius: 4, backgroundColor: color),
                        const SizedBox(width: 6),
                        Text(
                          label,
                          style: TextStyle(color: color, fontSize: 11, fontWeight: FontWeight.bold),
                        ),
                      ],
                    ),
                  ),
                ),
              );
            },
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(20.0),
        child: Column(
          children: [
            StreamBuilder<MarketTick>(
              stream: _wsService.marketStream,
              builder: (context, snapshot) {
                if (snapshot.hasData) {
                  final tick = snapshot.data!;
                  _handlePriceUpdate(tick);

                  return AnimatedContainer(
                    duration: const Duration(milliseconds: 250),
                    curve: Curves.easeInOut,
                    padding: const EdgeInsets.all(24),
                    decoration: BoxDecoration(
                      color: _flashColor,
                      borderRadius: BorderRadius.circular(24),
                      border: Border.all(color: Colors.grey.shade300),
                    ),
                    child: Column(
                      children: [
                        Text(
                          tick.symbol,
                          style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold, letterSpacing: 1.2),
                        ),
                        const SizedBox(height: 8),
                        Text(
                          '\$${tick.price.toStringAsFixed(2)}',
                          style: const TextStyle(fontSize: 40, fontWeight: FontWeight.w900),
                        ),
                        const SizedBox(height: 8),
                        Text(
                          'Volume: ${tick.volume.toStringAsFixed(4)} BTC',
                          style: const TextStyle(fontSize: 13, color: Colors.black54),
                        ),
                        const SizedBox(height: 4),
                        Text(
                          'Last Update: ${tick.timestamp.toLocal().toString().split('.')[0]}',
                          style: const TextStyle(fontSize: 11, color: Colors.grey),
                        ),
                      ],
                    ),
                  );
                }

                return Container(
                  height: 160,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: Colors.grey.shade100,
                    borderRadius: BorderRadius.circular(24),
                  ),
                  child: const Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      CircularProgressIndicator(),
                      SizedBox(height: 14),
                      Text('Subscribing to WSS Trading Stream...'),
                    ],
                  ),
                );
              },
            ),
            const SizedBox(height: 24),
            Expanded(
              child: Card(
                elevation: 0,
                color: Colors.grey.shade50,
                shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
                child: const Padding(
                  padding: EdgeInsets.all(20),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'Architectural Highlights',
                        style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16),
                      ),
                      SizedBox(height: 12),
                      Text('• Full-duplex persistent TCP socket via IOWebSocketChannel.'),
                      SizedBox(height: 8),
                      Text('• Heartbeat ping-pong mechanism guards against half-open sockets.'),
                      SizedBox(height: 8),
                      Text('• Exponential backoff with randomized jitter prevents thundering herds.'),
                      SizedBox(height: 8),
                      Text('• Multi-subscriber UI binding using StreamController.broadcast().'),
                    ],
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Broadcast StreamController Decoupling**:
   `ResilientWebSocketService` maps the single-subscription socket stream into `_marketDataController.stream.broadcast()`. This allows multiple independent Flutter widgets (e.g. status bar pill, pricing card, order book) to listen simultaneously without throwing `Bad state: Stream has already been listened to`.
2. **Automated Heartbeat Watchdog**:
   `_startHeartbeat()` executes `_sendPing()` every 15 seconds. It dispatches a ping frame and arms a 4-second `_pongWatchdogTimer`. If the server fails to reply with `pong` before the timer expires, the socket is assumed half-open and forcibly closed, initiating an immediate reconnect.
3. **Exponential Backoff with Random Jitter**:
   `_scheduleReconnect()` increases the delay exponentially (`baseBackoff = min(pow(2, _reconnectAttempts), 30)`) and appends random jitter (`Random().nextInt(1000)`). This prevents mobile clients from synchronizing reconnect storms against recovering infrastructure.
4. **Reactive UI with Animated Color Flashing**:
   `_handlePriceUpdate(tick)` compares the incoming price with `_lastPrice`, flashing the card green on price appreciation or red on price depreciation via an `AnimatedContainer`.
